/**
 * Inline Lucide SVG (stroke 2.25, round caps/joins). Directional icons mirror in RTL via .lk-icon-dir.
 */
function linkawy_icon($name, $size = 20, $class = '') {
    static $paths = null;
    if ($paths === null) {
        $paths = linkawy_lucide_paths();
    }
    if (!isset($paths[$name])) {
        return '';
    }
    $dir = in_array($name, array('ArrowRight', 'ArrowLeft', 'ArrowUpRight', 'ChevronRight', 'ChevronLeft', 'Send'), true) ? ' lk-icon-dir' : '';
    $size = (int) $size;
    return '<svg class="lk-icon' . $dir . ($class ? ' ' . esc_attr($class) : '') . '" xmlns="http://www.w3.org/2000/svg" width="' . $size . '" height="' . $size . '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.25" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">' . $paths[$name] . '</svg>';
}
